if __name__ == '__main__':
    import re as _re
    import statistics as _stats
    assert len(BODIES_103) == 30
    _lens = []
    _ban = ('the overview', 'from the overview', 'as in the overview', 'in the overview')
    for _cid, _b in BODIES_103.items():
        _ov = _b['solution_overview']
        assert 200 <= len(_ov) <= 800, (_cid, len(_ov))
        assert len(_b['tactical_explanations']) == 5
        for _i, _e in enumerate(_b['tactical_explanations']):
            assert _e.startswith('**' + 'ABCDE'[_i] + '.** → ')
            assert _re.search(r'So the statement is (True|False)\.\s*$', _e.strip())
            assert _e.count('$$') % 2 == 0
            assert len(_e) >= 180, (_cid, _i, len(_e))
            _low = _e.lower()
            for _bans in _ban:
                assert _bans not in _low, (_cid, _i, _bans)
            _lens.append(len(_e))
    _med = _stats.median(_lens)
    assert _med >= 300, _med
    print(
        'OK', len(BODIES_103),
        'mean', round(_stats.mean(_lens)),
        'median', _med,
        'min', min(_lens),
        'max', max(_lens),
        'ov', round(_stats.mean([len(b['solution_overview']) for b in BODIES_103.values()])),
    )

